const L_RUNTIME_CAPTURE = `LANE: runtime-capture + public API (page runtime part 2 — the integration point). Everything else in scene3d/film is DONE: read ${HB}/scene3d/film/** completely first.
Files you own: ${HB}/scene3d/film/runtime/{recorder.js, take_player.js, jev_bridge_page.js}, ${HB}/scene3d/film/index.js; tests ${HB}/tests/film_runtime_capture.test.mjs, ${HB}/tests/film_api.test.mjs.
Read ${SP}/recon_capture.md and ${SP}/recon_hud.md first. Implement SPEC §3 (+§3.2 bridge):
- recorder.js: createRecorder({canvas, fps, width, height, codec:'avc'|'vp9'|'frames', bitrate=40e6, keyIntervalSec=2, VideoEncoder, VideoFrame (injectable, default globalThis), log}) → {start(), grab(filmTimeSec) (synchronous: new VideoFrame(canvas,{timestamp:µs, duration}) → encoder.encode(frame,{keyFrame}) → frame.close(); 'frames' mode: canvas.toDataURL('image/jpeg', q) queued), waitForCapacity() (backpressure on encodeQueueSize), drain({maxBytes}) → {chunks:[{seq, b64, timestampUs, key, type}], done, stats}, stop() → flush → final, stats()}. H.264: config {codec:'avc1.640033', width, height, bitrate, framerate:fps, latencyMode:'quality', avc:{format:'annexb'}, hardwareAcceleration:'prefer-hardware'} with VideoEncoder.isConfigSupported fallback chain (avc1.640033 → avc1.4d0033 → vp09.00.40.08 → 'frames'); base64 encode chunk bytes efficiently (chunked String.fromCharCode + btoa, or Buffer when present).
- take_player.js: createTakePlayer({cameraOwner, clock, sensors, pilot, safety, recorder?, drone (flight_model), worldQuery, log}) → {prepare(take) (take = {shot spec | baked table, ctx overrides, pilot cfg, capture cfg, standingOrder}), rehearse() → {realisedTable, checksum, pilotTelemetry, safetyEvents}, shoot({mode:'stepped'|'realtime', locked}) → take report {frames, durationSec, realisedChecksum, pilot:{decisions, sources, agreement}, safety:{adjustedFrames}, obstruction:{minVisibleFrac, framesHidden}, recorder stats}}. Per frame exactly SPEC §3 order: nominal = traj.sample(progress) → drone dynamics for drone/fpv families → pilot residual (offsets in the path frame built from the trajectory tangent; speedScale warps progress; distanceScale scales distance to subject) → safety.clamp → cameraOwner.write → clock.step() (render) → recorder.grab inside the postRender hook. Pre-roll ≥ 6 frames rendered but not recorded after a cut. Realtime mode: drive with requestAnimationFrame and wall-clock timestamps, pilot.tick (async). Locked mode replays a realised table (no pilot).
- jev_bridge_page.js: createPageBridge({window, timeoutMs}) per SPEC §3.2 (window.__filmJev(json) → Promise<json>; parse; timeout; never throws into the pilot; available flag re-evaluated per request).
- index.js: export installFilmMode({liveScene3d, THREE, sessionHandle, wasmExports, log}) → api; build all runtime pieces (camera owner, clock with dynamic imports of ../particles/time_rng.js etc. — dynamic import inside the function is fine; typeof-guard the hooks lane's exports), the perception stack, pilot (bridge = page bridge; mode from take/pilot cfg), technique registry (./shots/index.js); install window.__film with EVERY method of the SPEC §3 table, each returning {ok:false, error} instead of throwing, JSON-safe outputs; scout(shot, {count, stills, width}) = solver.generateCandidates + per-candidate metrics via sensors/los/framing (+ JPEG stills via a stepped render + canvas.toDataURL in the postRender hook when stills); prepare/rehearse/shoot delegate to take_player; recorder.drain proxies; status(); techniques(). Expose version 'film-1'. Idempotent install (second call returns the existing api).
Tests: fake VideoEncoder/VideoFrame classes (assert config fallback chain, timestamps µs = round(frame/fps·1e6), keyframe interval, close() called, backpressure waits, drain chunking by maxBytes, annexb bytes preserved through base64); take_player end-to-end with fakes (static trajectory + fake sensors/pilot/safety/clock): frame count = duration·fps (+pre-roll not recorded), pilot speedScale<1 extends progress time, safety adjustments recorded, locked replay reproduces the realised checksum; page bridge timeout/available; installFilmMode on a fake liveScene3d exposes every SPEC method, methods never throw (call each with bad input → {ok:false}), status JSON-serialisable.`

phase('Core')
const core = await agent(PRE + '\n\n' + L_CORE, { label: 'lane:core', phase: 'Core', schema: REPORT })
log('core done: ' + (core ? core.tests.map(t => t.file + ' ' + t.passed + '/' + (t.passed + t.failed)).join(', ') : 'FAILED'))

phase('Shots+Pilot')
const [shotsCore, pilot] = await parallel([
  () => agent(PRE + '\n\n' + L_SHOTS_CORE, { label: 'lane:shots-core', phase: 'Shots+Pilot', schema: REPORT }),
  () => agent(PRE + '\n\n' + L_PILOT, { label: 'lane:pilot', phase: 'Shots+Pilot', schema: REPORT }),
])

phase('Techniques+Scene')
const [classic, drone, scenePure] = await parallel([
  () => agent(PRE + '\n\n' + L_CLASSIC, { label: 'lane:classic', phase: 'Techniques+Scene', schema: REPORT }),
  () => agent(PRE + '\n\n' + L_DRONE, { label: 'lane:drone', phase: 'Techniques+Scene', schema: REPORT }),
  () => agent(PRE + '\n\n' + L_SCENE_PURE, { label: 'lane:scene-pure', phase: 'Techniques+Scene', schema: REPORT }),
])

phase('Runtime')
const perception = await agent(PRE + '\n\n' + L_PERCEPTION, { label: 'lane:perception', phase: 'Runtime', schema: REPORT })
const runtimeCam = await agent(PRE + '\n\n' + L_RUNTIME_CAM, { label: 'lane:runtime-camera', phase: 'Runtime', schema: REPORT })
const runtimeCap = await agent(PRE + '\n\n' + L_RUNTIME_CAPTURE, { label: 'lane:runtime-capture', phase: 'Runtime', schema: REPORT })

return { core, shotsCore, pilot, classic, drone, scenePure, perception, runtimeCam, runtimeCap }